import type { PaymentMethod } from "./order";
import type { Currency } from "./product";

/**
 * Wire contracts for storefront orders (in-store pickup). Lifecycle and rules:
 * docs/online-orders-plan.md.
 */

export type OnlineOrderStatus = "AWAITING_PAYMENT" | "CONFIRMED" | "READY" | "COLLECTED" | "CANCELLED" | "EXPIRED";
export type OnlineOrderPaymentMethod = "KHQR" | "PAY_AT_COUNTER";
export type OnlineOrderCancelReason = "STAFF" | "UNCOLLECTED";

export interface PlaceOnlineOrderRequest {
  /** Generated by the browser once per checkout attempt; retrying with the same value returns the same order. */
  clientOrderUuid: string;
  items: Array<{ productId: string; quantity: number }>;
  customerName: string;
  customerPhone: string;
  note?: string | null;
  /** ISO timestamp of a slot from /pickup-slots, or null for "as soon as it's ready". */
  pickupAt: string | null;
  paymentMethod: OnlineOrderPaymentMethod;
}

/** 409 body when an item no longer has enough stock; nothing is reserved in that case. */
export interface StockShortageError {
  error: string;
  shortages: Array<{ productId: string; name: string; available: number }>;
}

export interface OnlineOrderLine {
  productId: string;
  name: string;
  quantity: number;
  /** Unit price as charged, in the product's own currency. */
  price: number;
  currency: Currency;
}

export interface OnlineOrderKhqr {
  qrString: string;
  /** The amount encoded in the QR, in `currency` (the store's main currency). */
  amount: number;
  currency: Currency;
  expiresAt: string;
}

/** What the shopper sees at /orders/:token. The phone number is never returned in full. */
export interface PublicOnlineOrder {
  token: string;
  storeId: string;
  storeName: string;
  pickupCode: string;
  status: OnlineOrderStatus;
  paymentMethod: OnlineOrderPaymentMethod;
  customerName: string;
  customerPhoneLast3: string;
  note: string | null;
  pickupAt: string | null;
  holdUntil: string | null;
  items: OnlineOrderLine[];
  /** Always USD; KHR-priced lines converted at `exchangeRate`. */
  totalAmount: number;
  currency: "USD";
  exchangeRate: number;
  /** Present only while the order is AWAITING_PAYMENT. */
  khqr: OnlineOrderKhqr | null;
  cancelReason: OnlineOrderCancelReason | null;
  createdAt: string;
  paidAt: string | null;
  readyAt: string | null;
  collectedAt: string | null;
  cancelledAt: string | null;
}

/** Staff view (IMS): the public view plus the internal id, full phone, and how a counter payment was taken. */
export interface StaffOnlineOrder extends Omit<PublicOnlineOrder, "khqr" | "customerPhoneLast3"> {
  id: string;
  customerPhone: string;
  collectedPaymentMethod: PaymentMethod | null;
}

export interface PickupSlotsResponse {
  /** "As soon as it's ready" is always offered; when the branch is closed it means "when it next opens". */
  asap: { availableNow: boolean; opensAt: string | null };
  /** ISO start times of 30-minute slots, today and tomorrow, inside opening hours. Empty when hours aren't listed. */
  slots: string[];
}

export interface CollectOnlineOrderRequest {
  /** Required for PAY_AT_COUNTER orders: how the shopper actually paid at the counter. */
  paymentMethod?: PaymentMethod;
}
